{
  "case_goal": "Enrol user 'UserU' into a course by searching for 'Math' and completing the enrolment.",
  "summary": "The test navigates to Claroline, logs in with user 'UserU', clicks 'Enrol on a new course', searches for 'Math', clicks the enrolment icon for the Math course, and verifies the enrolment confirmation page.",
  "steps": [
    {
      "action_type": "get",
      "target": "url",
      "value": "http://claroline-old.local:8088/",
      "page_url": "http://claroline-old.local:8088/",
      "expected_result": "Page loads with login form and category links."
    },
    {
      "action_type": "login",
      "target": "login form",
      "value": "UserU / passwordU",
      "page_url": "http://claroline-old.local:8088/",
      "expected_result": "After login, user sees logged-in menu with 'Enrol on a new course' link."
    },
    {
      "action_type": "click",
      "target": "link text: Enrol on a new course",
      "value": "",
      "page_url": "http://claroline-old.local:8088/claroline/auth/courses.php?cmd=rqReg&category=",
      "expected_result": "Page displays course enrolment options and a search field."
    },
    {
      "action_type": "send_keys and submit",
      "target": "id=keyword",
      "value": "Math",
      "page_url": "http://claroline-old.local:8088/claroline/auth/courses.php",
      "expected_result": "Search results show a course with 'Math' and an enrolment icon (a > img)."
    },
    {
      "action_type": "click",
      "target": "css selector: a > img",
      "value": "",
      "page_url": "http://claroline-old.local:8088/claroline/auth/courses.php?cmd=exReg&course=1b2e",
      "expected_result": "Enrolment is completed, page shows 'Back to my personal course list' link."
    },
    {
      "action_type": "find_element",
      "target": "xpath: //*[@id='claroBody']/blockquote/table/tbody/tr/td/p[1]",
      "value": "",
      "page_url": "http://claroline-old.local:8088/claroline/auth/courses.php?cmd=exReg&course=1b2e",
      "expected_result": "Element exists, confirming successful enrolment message."
    }
  ]
}
